/* trigger_jetson.c: trigger pulses from a Jetson's (or any Linux board's) GPIO lines, generated by Vantage for
 * @@PROJECT@@ · @@VARIANT@@.
 *
 * Userspace, so the edges are as good as the kernel wakes the thread: each edge is an absolute clock_nanosleep on
 * the system clock followed by a libgpiod write, in a SCHED_FIFO thread with its memory locked. On a stock kernel the
 * wake-up is late by tens of microseconds typically and by hundreds at worst; PREEMPT_RT shortens the tail. Measure
 * your unit: run with --stats (it prints the lateness of every edge as percentiles), and cyclictest for the kernel's
 * own figure. For sub-microsecond triggers use the RP2040 or STM32 box instead.
 *
 * Time: the schedule is laid on whole seconds of the system clock (--clock realtime, or tai), which chrony (PPS
 * refclock) or ptp4l + phc2sys discipline to GNSS: the PPS discipline happens in the operating system. With
 * --pps /dev/ppsN (a pps-gpio device, built with -DTB_HAVE_TIMEPPS and pps-tools' timepps.h) the PPS assert stamps
 * discipline the schedule directly, through the same scheduling core as the microcontroller boxes.
 *
 * Only trigger pulses come out of this program. It drives nothing else.
 */
#define _GNU_SOURCE
#include <errno.h>
#include <pthread.h>
#include <sched.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <time.h>

#include "gpio.h"
#include "trigger_core.h"
#include "trigger_plan.h"

#ifdef TB_HAVE_TIMEPPS
#include <fcntl.h>
#include <sys/timepps.h>
#endif

static volatile sig_atomic_t stop;
static clockid_t clk = CLOCK_REALTIME;

static void on_signal(int sig) { (void)sig; stop = 1; }

static int64_t now_ns(void)
{
    struct timespec ts;
    clock_gettime(clk, &ts);
    return (int64_t)ts.tv_sec * 1000000000 + ts.tv_nsec;
}

static void sleep_until(int64_t t)
{
    struct timespec ts;
    ts.tv_sec = (time_t)(t / 1000000000);
    ts.tv_nsec = (long)(t % 1000000000);
    while (clock_nanosleep(clk, TIMER_ABSTIME, &ts, NULL) == EINTR && !stop) {
    }
}

/* ---- the PPS thread (--pps): assert stamps handed to the main loop */
static pthread_mutex_t pps_lock = PTHREAD_MUTEX_INITIALIZER;
static int64_t pps_stamp = -1;

#ifdef TB_HAVE_TIMEPPS
static void *pps_thread(void *arg)
{
    pps_handle_t h;
    int fd = open((const char *)arg, O_RDWR);
    pps_info_t info;
    struct timespec timeout = {2, 0};
    if (fd < 0 || time_pps_create(fd, &h) < 0) {
        fprintf(stderr, "cannot open the PPS device %s\n", (const char *)arg);
        return NULL;
    }
    while (!stop) {
        if (time_pps_fetch(h, PPS_TSFMT_TSPEC, &info, &timeout) == 0) {
            int64_t t = (int64_t)info.assert_timestamp.tv_sec * 1000000000 + info.assert_timestamp.tv_nsec;
            pthread_mutex_lock(&pps_lock);
            pps_stamp = t;
            pthread_mutex_unlock(&pps_lock);
        }
    }
    time_pps_destroy(h);
    return NULL;
}
#endif

static int cmp64(const void *a, const void *b)
{
    int64_t x = *(const int64_t *)a, y = *(const int64_t *)b;
    return (x > y) - (x < y);
}

int main(int argc, char **argv)
{
    const tb_plan_t *plan = &TB_PLAN;
    const char *chip = TB_GPIO_CHIP, *pps = NULL;
    double seconds = 0.0;
    int stats = 0, prio = 80, i;
    unsigned offsets[TB_MAX_LINES];
    tb_state_t st;
    int64_t next_sec, start, last_pps_seen = -1;
    int64_t *late = NULL;
    size_t n_late = 0, cap_late = 0;
    uint32_t state;

    memcpy(offsets, TB_GPIO_OFFSETS, sizeof offsets);
    for (i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "--selftest"))
            plan = &TB_PLAN_SELFTEST;
        else if (!strcmp(argv[i], "--stats"))
            stats = 1;
        else if (!strcmp(argv[i], "--clock") && i + 1 < argc)
            clk = !strcmp(argv[++i], "tai") ? CLOCK_TAI : CLOCK_REALTIME;
        else if (!strcmp(argv[i], "--pps") && i + 1 < argc)
            pps = argv[++i];
        else if (!strcmp(argv[i], "--chip") && i + 1 < argc)
            chip = argv[++i];
        else if (!strcmp(argv[i], "--seconds") && i + 1 < argc)
            seconds = atof(argv[++i]);
        else if (!strcmp(argv[i], "--prio") && i + 1 < argc)
            prio = atoi(argv[++i]);
        else if (!strcmp(argv[i], "--lines") && i + 1 < argc) {
            char *s = argv[++i];
            unsigned k;
            for (k = 0; k < plan->n_lines && s && *s; k++) {
                offsets[k] = (unsigned)strtoul(s, &s, 10);
                if (*s == ',')
                    s++;
            }
        } else {
            fprintf(stderr, "usage: %s [--clock realtime|tai] [--pps /dev/ppsN] [--chip NAME] [--lines o1,o2,...] "
                            "[--selftest] [--stats] [--seconds N] [--prio P]\n", argv[0]);
            return 2;
        }
    }
    signal(SIGINT, on_signal);
    signal(SIGTERM, on_signal);
    if (mlockall(MCL_CURRENT | MCL_FUTURE) != 0)
        fprintf(stderr, "note: memory not locked (%s)\n", strerror(errno));
    {
        struct sched_param sp;
        sp.sched_priority = prio;
        if (prio > 0 && sched_setscheduler(0, SCHED_FIFO, &sp) != 0)
            fprintf(stderr, "note: no real-time priority (%s): edges will be later and less even\n", strerror(errno));
    }
    if (gpio_open(chip, offsets, plan->n_lines, TB_OUT_INVERT) != 0) {
        fprintf(stderr, "cannot open the GPIO lines on %s\n", chip);
        return 1;
    }
#ifdef TB_HAVE_TIMEPPS
    if (pps) {
        pthread_t th;
        pthread_create(&th, NULL, pps_thread, (void *)pps);
        pthread_detach(th);
    }
#else
    if (pps) {
        fprintf(stderr, "built without TB_HAVE_TIMEPPS: --pps needs pps-tools' timepps.h\n");
        return 2;
    }
#endif
    start = now_ns();
    tb_init(&st, plan, start);
    next_sec = (start / 1000000000 + 1) * 1000000000;
    while (!stop) {
        int64_t edge, now = now_ns(), got;
        if (seconds > 0 && now - start > (int64_t)(seconds * 1e9))
            break;
        if (pps) {                                /* the PPS device's stamps */
            pthread_mutex_lock(&pps_lock);
            got = pps_stamp;
            pthread_mutex_unlock(&pps_lock);
            if (got >= 0 && got != last_pps_seen) {
                tb_on_pps(&st, got);
                last_pps_seen = got;
            }
        } else {                                  /* the disciplined clock's whole seconds are the PPS */
            while (next_sec <= now) {
                tb_on_pps(&st, next_sec);
                next_sec += 1000000000;
            }
        }
        tb_poll(&st, now);
        tb_next_edge(&st, &edge, &state);
        sleep_until(edge);
        if (stop)
            break;
        gpio_write(state ^ TB_OUT_INVERT);
        if (stats) {
            int64_t d = now_ns() - edge;          /* how late the line changed (after the write returned) */
            if (n_late == cap_late) {
                cap_late = cap_late ? 2 * cap_late : 4096;
                late = realloc(late, cap_late * sizeof *late);
                if (!late)
                    return 1;
            }
            late[n_late++] = d;
        }
    }
    gpio_write(TB_OUT_INVERT);                    /* every line idle */
    gpio_close();
    if (stats && n_late) {
        qsort(late, n_late, sizeof *late, cmp64);
        printf("edges=%zu late_us p50=%.1f p90=%.1f p99=%.1f p999=%.1f max=%.1f state=%s pps=%u\n", n_late,
               late[n_late / 2] / 1e3, late[n_late * 9 / 10] / 1e3, late[n_late * 99 / 100] / 1e3,
               late[n_late * 999 / 1000] / 1e3, late[n_late - 1] / 1e3, tb_state_name(st.state), st.pps);
    }
    free(late);
    return 0;
}
